pub use ai_studio::{AiStudioConnection, AiStudioPanel};

/// Runs one ADR 0142 benchmark experiment from a versioned JSON configuration.
///
/// The runner uses repository-owned per-run fixtures and child Editor processes;
/// it never benchmarks the caller's currently open project.
pub fn run_agent_benchmark_experiment(config_path: &std::path::Path) -> Result<(), String> {
    agent_benchmark_experiment::run_experiment_cli(config_path)
}
